import csv
# Check if the selected matrix has any fields that contain commas, quotes, or newlines
with open('outputs/t12_selected_matrix.csv', 'r', encoding='utf-8') as f:
    reader = csv.reader(f)
    rows = list(reader)
    for i, row in enumerate(rows):
        for j, field in enumerate(row):
            if ',' in field or '\"' in field or '\n' in field:
                print(f'Row {i}, Field {j}: {repr(field)}')
print('Check complete')
